function FeedbackBar({value,onChange,load=true}:{value:Feedback;onChange:(v:Feedback)=>void;load?:boolean}){return <div className="feedback-bar" role="group" aria-label={load?'Ressenti de la charge':'Ressenti de l’exécution'}>{([['trop_dur',load?'Trop dur':'Difficile',load?'Réduire':'À ajuster'],['ok',load?'Charge bonne':'Bien',load?'Consolider':'Satisfaisant'],['facile','Facile',load?'Augmenter':'À l’aise']] as const).map(([id,name,sub])=><button key={id} className={value===id?'selected':''} onClick={()=>onChange(id)} aria-pressed={value===id}><strong>{name}</strong><small>{sub}</small></button>)}</div>}
