 async function start(model:Model){if(!dataRef.current)return;if(dataRef.current.settings.audio!=='silent'&&!await unlockAudio())toast.error('Son bloqué : essaie « Tester le son » dans les réglages.');const loading=preloadAudio([...dataRef.current.program.catalogue.map(e=>e.id),'repos','dix_secondes','cote_gauche','cote_droite','fini','on_commence']);const run=makeRun(model,dataRef.current.program,dataRef.current.sessions,dataRef.current.settings.reduced);commit({...dataRef.current,running:run});setSelected(null);restoreGuard.current=false;void acquireWake();void loading.then(()=>{if(dataRef.current?.running?.uuid===run.uuid&&dataRef.current.settings.audio==='voice')voice('on_commence')})}
