 function saveExercise(ex:Exercise,model?:Model,entry?:Entry){if(model&&entry){if(ex.intercalaire===false)entry={...entry,intercalaire_de:[]};if(ex.intercalaire===true&&!entry.intercalaire_de.length){const parent=model.exercices.filter(e=>!e.intercalaire_de.length&&e.ordre!==entry!.ordre&&e.ordre<entry!.ordre).at(-1);if(parent)entry={...entry,intercalaire_de:[parent.ordre]}}saveVersion({...model,exercices:model.exercices.map(e=>e.ordre===entry!.ordre?entry!:e)},ex);return}const d=dataRef.current!;commit({...d,program:{...d.program,catalogue:d.program.catalogue.map(e=>e.id===ex.id?ex:e)},pending:[...new Set([...d.pending,'program'])]});toast.success('Exercice enregistré.');void sync()}
